styles:
.b-reviews {
    container-type: inline-size;
    --reviews-gap: 1.5em;
}

.b-reviews__title {
    margin: 0 0 1em;
}

.b-reviews__filter {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5em;
    margin: 0 0 1.25em;
}

/* A flex or grid box outranks the browser's own [hidden] rule. */
.b-reviews__filter[hidden],
.b-reviews__nav[hidden],
.b-reviews__item[hidden] {
    display: none;
}

.b-reviews__chip {
    font: inherit;
    color: inherit;
    background: none;
    border: 1px solid currentColor;
    border-radius: 999px;
    padding: 0.35em 0.9em;
    cursor: pointer;
    opacity: 0.65;
}

.b-reviews__chip.is-active {
    opacity: 1;
    font-weight: 600;
}

/* The grid, and what every other layout starts from. Up to `--reviews-columns` across, fewer
   when a column would be narrower than 16em. */
.b-reviews__track {
    display: grid;
    grid-template-columns: repeat(
        auto-fill,
        minmax(min(100%, max(16em, (100% - (var(--reviews-columns, 3) - 1) * var(--reviews-gap)) / var(--reviews-columns, 3))), 1fr)
    );
    gap: var(--reviews-gap);
    margin: 0;
    padding: 0;
    list-style: none;
}

.b-reviews__item {
    min-width: 0;
}

.b-reviews__card {
    display: flex;
    flex-direction: column;
    gap: 0.75em;
    box-sizing: border-box;
    height: 100%;
    margin: 0;
    padding: 1.5em;
    border: 1px solid color-mix(in srgb, currentColor 15%, transparent);
    border-radius: 0.75em;
}

.b-reviews__photo,
.b-reviews__initials {
    flex: none;
    width: 3.5em;
    height: 3.5em;
    border-radius: 50%;
}

.b-reviews__photo {
    object-fit: cover;
}

.b-reviews__initials {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    background: color-mix(in srgb, currentColor 10%, transparent);
}

/* Five stars, filled as far as the rating goes. */
.b-reviews__stars {
    position: relative;
    display: inline-block;
    width: max-content;
    line-height: 1;
    letter-spacing: 0.15em;
    font-size: 1.1em;
}

.b-reviews__stars::before {
    content: '★★★★★';
    opacity: 0.2;
}

.b-reviews__stars::after {
    content: '★★★★★';
    position: absolute;
    top: 0;
    left: 0;
    width: calc(var(--rating, 0) / 5 * 100%);
    overflow: hidden;
    white-space: nowrap;
}

.b-reviews__text {
    flex: 1;
    margin: 0;
}

.b-reviews__caption {
    display: flex;
    flex-direction: column;
    gap: 0.15em;
}

.b-reviews__name {
    font-weight: 600;
    color: inherit;
}

.b-reviews__job,
.b-reviews__date {
    font-size: 0.9em;
    opacity: 0.7;
}

/* One: a single review, large. */
.b-reviews[data-reviews-layout='single'] .b-reviews__track {
    display: block;
    max-width: 48em;
    margin-inline: auto;
}

.b-reviews[data-reviews-layout='single'] .b-reviews__card {
    align-items: center;
    text-align: center;
    border: 0;
    font-size: 1.125em;
}

/* A slider and a marquee are a ribbon that scrolls sideways — without the script, too. */
.b-reviews[data-reviews-layout='slider'] .b-reviews__viewport,
.b-reviews[data-reviews-layout='marquee'] .b-reviews__viewport {
    overflow-x: auto;
    scrollbar-width: thin;
}

.b-reviews[data-reviews-layout='slider'] .b-reviews__track,
.b-reviews[data-reviews-layout='marquee'] .b-reviews__track {
    display: flex;
}

.b-reviews[data-reviews-layout='slider'] .b-reviews__viewport {
    scroll-snap-type: x mandatory;
}

.b-reviews[data-reviews-layout='slider'] .b-reviews__item {
    flex: 0 0 calc((100% - (var(--reviews-columns, 3) - 1) * var(--reviews-gap)) / var(--reviews-columns, 3));
    scroll-snap-align: start;
}

@container (max-width: 40em) {
    .b-reviews[data-reviews-layout='slider'] .b-reviews__item {
        flex-basis: 85%;
    }
}

.b-reviews__nav {
    display: flex;
    justify-content: flex-end;
    gap: 0.5em;
    margin-top: 1em;
}

.b-reviews__arrow {
    width: 2.5em;
    height: 2.5em;
    font: inherit;
    color: inherit;
    background: none;
    border: 1px solid currentColor;
    border-radius: 50%;
    cursor: pointer;
}

.b-reviews__arrow:disabled {
    opacity: 0.35;
    cursor: default;
}

.b-reviews[data-reviews-layout='marquee'] .b-reviews__track {
    width: max-content;
}

.b-reviews[data-reviews-layout='marquee'] .b-reviews__item {
    flex: 0 0 20em;
}

/* The script doubles the ribbon and runs it by half its length, so the end meets the start. */
.b-reviews.is-running .b-reviews__viewport {
    overflow: hidden;
}

.b-reviews.is-running .b-reviews__track {
    animation: b-reviews-marquee var(--reviews-duration, 40s) linear infinite;
}

.b-reviews.is-running .b-reviews__track:hover,
.b-reviews.is-running .b-reviews__track:focus-within {
    animation-play-state: paused;
}

@keyframes b-reviews-marquee {
    to {
        transform: translateX(calc(-50% - var(--reviews-gap) / 2));
    }
}

@media (prefers-reduced-motion: reduce) {
    .b-reviews.is-running .b-reviews__track {
        animation: none;
    }

    .b-reviews.is-running .b-reviews__viewport {
        overflow-x: auto;
    }
}

script:
const layout = el.dataset.reviewsLayout || 'grid'
const viewport = el.querySelector('.b-reviews__viewport')
const track = el.querySelector('.b-reviews__track')
const chips = Array.from(el.querySelectorAll('.b-reviews__chip'))
const filter = el.querySelector('.b-reviews__filter')
const still = window.matchMedia('(prefers-reduced-motion: reduce)')
const items = () => Array.from(el.querySelectorAll('.b-reviews__item'))

// The filter is printed hidden: without this script its buttons would do nothing.
if (filter) filter.hidden = false

for (const chip of chips) {
  chip.addEventListener('click', () => {
    const group = chip.dataset.reviewsGroup || ''
    for (const other of chips) {
      const on = other === chip
      other.classList.toggle('is-active', on)
      other.setAttribute('aria-pressed', on ? 'true' : 'false')
    }
    for (const item of items()) {
      const groups = (item.dataset.reviewsCategories || '').split(' ')
      item.hidden = group !== '' && !groups.includes(group)
    }
    if (viewport) viewport.scrollLeft = 0
  })
}

if (layout === 'slider' && viewport && track) {
  const nav = el.querySelector('.b-reviews__nav')
  const arrows = nav ? Array.from(nav.querySelectorAll('.b-reviews__arrow')) : []
  if (nav) nav.hidden = false

  // One review further, measured rather than assumed: the number across changes with the width.
  const step = () => {
    const first = items().find((item) => !item.hidden)
    const gap = parseFloat(getComputedStyle(track).columnGap) || 0
    return first ? first.getBoundingClientRect().width + gap : viewport.clientWidth
  }
  const atEnd = () => viewport.scrollLeft + viewport.clientWidth >= viewport.scrollWidth - 2
  const go = (direction) => {
    const behavior = still.matches ? 'auto' : 'smooth'
    if (direction > 0 && atEnd()) viewport.scrollTo({ left: 0, behavior })
    else viewport.scrollBy({ left: direction * step(), behavior })
  }
  const update = () => {
    for (const arrow of arrows) {
      if (Number(arrow.dataset.reviewsStep) < 0) arrow.disabled = viewport.scrollLeft <= 1
    }
  }

  for (const arrow of arrows) {
    arrow.addEventListener('click', () => go(Number(arrow.dataset.reviewsStep) || 1))
  }
  viewport.addEventListener('scroll', update, { passive: true })
  update()

  if (el.dataset.reviewsAutoplay === 'on' && !still.matches) {
    let paused = false
    el.addEventListener('mouseenter', () => (paused = true))
    el.addEventListener('mouseleave', () => (paused = false))
    el.addEventListener('focusin', () => (paused = true))
    el.addEventListener('focusout', () => (paused = false))
    setInterval(() => {
      if (!paused && !document.hidden) go(1)
    }, 5000)
  }
}

if (layout === 'marquee' && viewport && track && !still.matches) {
  // A second copy of the ribbon for the eye only: the reader of a screen hears each review once.
  for (const item of items()) {
    const copy = item.cloneNode(true)
    copy.removeAttribute('id')
    copy.setAttribute('aria-hidden', 'true')
    for (const link of copy.querySelectorAll('a')) link.tabIndex = -1
    track.appendChild(copy)
  }

  const speed = Math.min(120, Math.max(10, Number(el.dataset.reviewsSpeed) || 40))
  const time = () => el.style.setProperty('--reviews-duration', `${track.scrollWidth / 2 / speed}s`)

  time()
  el.classList.add('is-running')
  if (typeof ResizeObserver === 'function') new ResizeObserver(time).observe(track)
}
